#!/usr/bin/env python3
# THE NUMBERS WALK, sitting 10 — THE VOWS (2026-09-12; the owner: "Go" after the #141 rereads, on the ruling READ THEN COMPILE): THE READING
# of Numbers 30:1-17 — ONE append-only ledger for the one draft (num_30_vows), written by one script from one reading pass. The spine: Onkelos
# Numbers 30 whole (17) + the Sifrei on Numbers piskaot 153-156 BY POSITION (17 rows; NO piska on 30:1 — 152:1's, credited). COVERAGE COMPUTED;
# THE INK FACTS computed (vows_ink.py, every fact an assert run by assert_driver.py — one fell on the first typed pass, an index typed from
# memory); every quotation CUT by consonants (the misses collected, asserted empty). Sitting 9's form.
import sys, os
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
from vows_ink import *
from vows_rows_onkelos import R
from vows_rows_sifrei import S
assert not os.path.exists(OUT), f'ledger exists — append, never overwrite: {OUT}'
assert FAIL == [], FAIL
assert sorted(R) == SPAN and sorted(S) == [(p, r) for p in PISKAOT for r in range(1, SIF_ROWS[p] + 1)], (len(R), len(S))

SHELF = ('- THE SHELF BY POSITION (computed on the export\'s rows): the Sifrei on Numbers has FOUR piskaot on chapter 30 — 153 (30:2, ten rows), 154 (30:10, three), 155 (30:14, one), 156 (headed "30:14" but opening on 30:15, three) — SEVENTEEN rows; NO piska on 30:1 (152:1, read whole at sitting 9, carries it as the calendar\'s closer — CREDITED with a quick look: its standing row speaks of 30:1 exactly); the next head, 157, is 31:1 (the next draft); every head asserted between its neighbors. THE ROWS\' OWN DEFECTS, read to their verses (RESEARCH_LOG.md): 156\'s head "30:14" for 30:15 — THE SEVENTH MISTYPED HEAD of the export (its first row quotes "silent, silent to her from day to day", 30:15\'s words); 153:3\'s English cites "II Kings 4:20" and glosses the speaker "(King David)" for the Hebrew\'s "2 Kings 2" — the words stand at 2 Kings 2:2, 2:4, 2:6 and 4:30, never at 4:20 and never in David\'s mouth; 153:3\'s and 153:4\'s ENGLISH SUPPLIES THE MISHNAH ("his vows are examined", "a girl of eleven", the identity\'s content "ki yafli") where the Hebrew rows carry neither; 153:7\'s Hebrew names "R. Yochanan" for R. Yonatan and concludes "so the FATHER" for the husband; 154:1\'s Hebrew closes "these are the words of R. Yishmael" and the English DROPS THE ATTRIBUTION; 154:2\'s English drops the Hebrew\'s conclusion ("leave to annul all the day"); 154:3\'s English drops the Hebrew\'s opening lemma (the caretaker excluded); 155:1\'s Hebrew breaks off "so the father can". No prior ledger had read an Onkelos row of 30 or a Sifrei row of 153-156 (nine ledgers NAME verses of the chapter as cross-references — a name is not a read); FRESH.')
PARSER = ('- THE ENGINE\'S PARSER ON THE CHAPTER (measured on cold_run_sequence.ink_numbers and ink_ordinals after 9b): NO cardinal and NO ordinal in seventeen verses — and the three OATH-tokens (30:3 "an oath", 30:11 "by an oath", 30:14 "the oath of"), spelled with the letters of "seven", STARRED as refused homographs: 3b\'s rule on the seven-stem\'s homographs holding at three new seats — silent-and-right, NO GAP; 31:1 empty too. The chapter\'s numbers are its clocks, not its counts: "on the day of his hearing" (four seats), "from day to day" (30:15) and "after his hearing" (30:16) — the compile\'s timers.')
REGISTER = ('- THE FRAMES AND THE REGISTER: TWO narrative verbs in seventeen verses, both Moses\' — 30:1 "and Moses SAID to the children of Israel according to all that the LORD commanded Moses" (the store\'s gloss "and-say"; the receipt formula\'s seven Bible seats — six close ACTS, this alone closes a SPEECH; the phrase "and Moses said to the children of Israel" two seats, Bezalel\'s calling the other) and 30:2 "and Moses SPOKE to the heads of the tribes ... this is the thing which the LORD commanded" ("and-speak"); NO divine speech-frame: the vows\' law is given in Moses\' voice — the formula "this is the thing which the LORD commanded" stands at eight Bible seats, and its two Numbers seats (30:2, 36:6) are exactly the book\'s two law chapters without "the LORD spoke to Moses" (computed on the frames of every chapter of Numbers); "the heads of the tribes" three Bible seats (Solomon\'s assembly the other two), "TO the heads" one; 30:3-16 Moses\' one speech; 30:17 "these are the statutes" the footer (three Bible seats, this alone without "and the judgments").')
INK = [
 '- THE CASE STRUCTURE (the compiler law\'s when/if, computed): TWO "when" cases open at the first word — 30:3 "a man, when he vows" and 30:4 "and a woman, when she vows" (the chapter\'s other two "ki" are "because": 30:6, 30:15) — and SEVEN "and if" branches (30:6, 7, 9, 11, 13, 15, 16); the draft\'s decision table carries exactly these nine rows; "a man, when" nine Torah seats; "and a woman, when" three — the woman with a discharge (Leviticus 15:19, 15:25) and this.',
 '- THE ROOTS (computed): "vow" fourteen tokens in the chapter (Numbers holds the Torah\'s vow-word most — twenty-two of forty, fourteen here), the bond-root twenty-two, the oath four; FIVE DOUBLED VERBS — "swear an oath" (30:3), "be, she shall be" (30:7; Jeremiah 15:18 its one kin), "annul, he annuls" (30:13, 30:16 — the form\'s two Bible seats, both here), "be silent, he is silent" (30:15, one seat) — and the cognate "bind a bond" (30:3); the stand-root twelve tokens, the annul-root six, the silence-verb four, the restrain-verb three (its fourth Torah seat the spies\' "discouraged", 32:9); ONKELOS KEEPS EVERY DOUBLING.',
 '- THE CLOCK WORDS (computed): "on the day of his hearing" FOUR seats, all here (30:6, 8, 13, 15), with 30:9\'s "on the day her husband hears" and 30:16\'s "AFTER his hearing" (one seat); the hearing-infinitive six tokens — the trigger; "FROM DAY TO DAY" (30:15) two Bible seats — this and 1 Chronicles 16:23, whose Psalm parallel (96:2) writes the words with the other preposition (Esther 3:7 the Psalm\'s form): the Chronicler keeps the Torah\'s; ONKELOS renders 30:15 with the Psalm\'s form.',
 '- THE FORGIVENESS AND THE INIQUITY (computed): "and the LORD will forgive her" THREE seats — all in this chapter (30:6 the father\'s restraint, 30:9 the husband\'s on the day, 30:13 the husband\'s in his house); the forgive-verb\'s fourth and last Bible token Naaman\'s plea (2 Kings 5:18); ONKELOS makes it passive behind its buffer — "from before the LORD it shall be forgiven her"; "and he shall bear HER iniquity" (30:16) one seat — "her iniquity" five Torah seats: the late-eaten peace offering (Leviticus 7:18), the land (18:25), THE SUSPECTED WIFE ("that woman shall bear her iniquity", 5:31), the blasphemer (15:31) and this; ONKELOS "he shall receive her guilt" (the debt-word).',
 '- THE PERSONS (computed): "her husband" NINE tokens (and "to a man" at 30:7) against "her father" SIX — the chapter\'s two authorities; "her soul" ten, "his soul" one, "a soul" one; "in her youth" TWO seats, both here (30:4, 30:17) — the priest\'s daughter returns to her father\'s house "AS in her youth" (Leviticus 22:13); "her father\'s house" seven Bible seats (Tamar\'s widowhood, the priest\'s daughter, this, the slandered bride, Rahab\'s, the concubine\'s two), "IN her father\'s house" one; "her husband\'s house" (30:11) here and Ruth 1:9; "a widow or a divorced woman" THREE Torah seats — the high priest\'s forbidden wives (Leviticus 21:14), the priest\'s daughter sent home (22:13) and this: the vower\'s widow and the priest\'s in one pair of words; ONKELOS renders "her husband" as "her OWNER" at all nine seats.',
 '- THE UTTERANCE (computed): "the utterance of her lips" (the noun) TWO seats, both here (30:7, 30:9) — its kin the oath-verb "to utter with the lips" of Leviticus 5:4 (one seat; the Sifrei\'s identity: utterance = oath); "all that proceeds from her lips" (30:13) one seat and its pair "what proceeds from your lips you shall keep" (Deuteronomy 23:24) one; "he shall not profane his word" one seat (the profane-verb in this sense here alone; its look-alikes "wait / begin" in Judges, Isaiah, Psalms); "according to all that proceeds from his mouth he shall do" one seat with two echoes — Moses to Gad and Reuben "what has gone out of your mouth you shall do" (32:24, the next portion) and Jephthah\'s daughter (Judges 11:36); "to afflict a soul" (30:14) — the infinitive\'s two Bible seats, Pharaoh\'s "to humble yourself" (Exodus 10:3) and this; ONKELOS: "the EXPLICIT [word] of her lips", "he shall not VOID his word", "to MORTIFY a soul".',
 '- ONKELOS\' ONE ROOT (cut from the shelf\'s bytes): the translation renders the OATH by the stand-root ("establishes an establishment" 30:3; "by an establishment" 30:11; "every establishment of a bond" 30:14), the CONFIRMING by the same root (30:5-15), and "the statutes" of 30:17 by it too — the chapter\'s stand-verb, its oath-noun and its statute-noun one Aramaic root where the Hebrew keeps three; "restrained" rendered "turned away"; "annul" rendered "void"; "before the LORD" for "to the LORD".',
 '- THE SHELF\'S CITATIONS READ TO THEIR VERSES (computed): the nazirite\'s "when he clearly utters to vow a vow" (6:2; "clearly utters" four Bible seats); Deuteronomy 23:22 "when you vow a vow to the LORD your God, you shall not DELAY to pay it" — the second transgression; Leviticus 5:4 "to utter with the lips"; the trumpets\' "they shall gather to you" (10:3-4); Moses\' "thus said the LORD" (Exodus 11:4); the princes returning first (Exodus 34:31-32); the king\'s-life oath at 2 Kings 2:2 (not "4:20", not David).',
]
CROWNS = [
 '- THE LAW IN MOSES\' VOICE: no "the LORD spoke to Moses" in the chapter — "this is the thing which the LORD commanded" opens it, and the formula\'s two Numbers seats (30:2, 36:6) are exactly the book\'s two law chapters without a divine frame; 30:1\'s receipt "according to all that the LORD commanded Moses" is the one of its seven seats that closes a SPEECH, not an act (computed on the frames and the first words).',
 '- TWO "WHEN" CASES AND SEVEN "AND IF" BRANCHES, the draft\'s nine rows exactly — the compiler law\'s case structure written on the chapter\'s first words; "a man, when" nine Torah seats, "and a woman, when" three (computed).',
 '- FIVE DOUBLED VERBS IN ONE CHAPTER — swear an oath, be she shall be, annul he annuls (its two Bible seats both here), be silent he is silent — every one kept by Onkelos and every one read by the Sifrei (R. Akiva\'s part-is-whole on "annul, annul"; the silence to vex on "silent, silent") (computed).',
 '- THE CLOCK IS THE CHAPTER\'S ONLY NUMBER: no cardinal, no ordinal, the oath-tokens starred; "on the day of his hearing" at four seats, "from day to day" at two in the Bible — the Chronicler\'s form the Torah\'s where the Psalm\'s differs — and the Sifrei\'s two settings (to nightfall; twenty-four hours, R. Shimon ben Yochai) the compile\'s parameter (computed).',
 '- "AND THE LORD WILL FORGIVE HER" — the clause\'s three Bible seats all in this chapter, the verb\'s fourth token Naaman\'s; Onkelos makes it passive behind its buffer; "he shall bear HER iniquity" the suspected wife\'s words (5:31) turned on the husband who annuls after confirming (computed).',
 '- THE WIDOW AND THE PRIEST\'S DAUGHTER SHARE A PAIR OF WORDS: "a widow or a divorced woman" three Torah seats — the high priest\'s forbidden wives, the priest\'s daughter who returns to her father\'s house "as in her youth", and the vower — and "in her youth" two seats, both here (computed).',
 '- THE SIFREI\'S ENGINE IS THE FOOTER: at four rows the induction is refused, the a-fortiori refused, and "these are the statutes ... between a man and his wife, between a father and his daughter" (30:17, "between" one seat each) decides — "you are compelled to liken"; and the Sifrei names its own move, "I reasoned and reversed" (155:1); the utterance = oath by Leviticus 5:4\'s one seat; the sage\'s release of vows "by experts alone" the Sifrei\'s own addition on a freed phrase (153:1).',
 '- ONKELOS\' ONE ROOT FOR OATH, CONFIRMATION AND STATUTE: "establishes an establishment", "by an establishment", "he shall establish them", "these are the establishments" — the Hebrew\'s three roots one in the translation (cut); "her husband" her OWNER at all nine seats; "restrained" turned away; "annul" void.',
 '- THE EXPORT\'S SEVENTH MISTYPED HEAD (156 "30:14" for 30:15), a citation and a speaker wrong in the English (2 Kings "4:20", "King David"), the English supplying the Mishnah at two rows, a name and a word garbled in the Hebrew, an attribution, a conclusion and a lemma dropped — nine defects read to their verses (computed on the bytes).',
]
TESTING = ('THE TESTING SHELF routed to Step 5 (the compile sitting\'s docket, per gap): Mishnah Nedarim chapters 9-11 (the release by a sage; vows of affliction and vows between him and her; the father, the betrothed maiden, the married woman, the widow and the divorcee) with Nedarim 66a-87b; Nedarim 77b-78a (the husband annuls, the sage permits — "this is the thing"; the heads of the tribes and the experts), Chagigah 10a (the release of vows "flies in the air"); Nedarim 10a-13b (the vow\'s support), Shevuot 20a-27a (utterance = oath; vows against oaths; binding the permitted; the inward oath); Niddah 45b-46a (the ages — thirteen and a day, twelve and a day, the examination); Nedarim 69a-73a (confirmed then annulled; the deaf; the report; restraint = annulment; the caretaker), Kiddushin 41b-42a (the messenger as the man); Nedarim 75a-76b (annulling in advance — R. Eliezer; what came to confirmation comes to annulment); Nedarim 76b-77a and Shabbat 157a (the day of hearing — till night or twenty-four hours; annulment on the Sabbath); Nedarim 79a (after confirmation — he bears her iniquity), Sanhedrin 100a and Yoma 76a (the measure of good against the measure of punishment); Rosh Hashanah 4a-6a (the delay ban — Deuteronomy 23:22, the three festivals); Yevamot 87a (the widow of betrothal); Sifrei Zuta and Numbers Rabbah outside scope.')
DECL = ('the portion Matot\'s first chapter read as ONE draft, num_30_vows 30:1-17 — 30:1 the portion Pinchas\'s last verse (the calendar\'s closer, the draft\'s-grain rule) and 30:2-17 the vows; the next draft (num_31_midian) opens at 31:1; chapters 28-29 frozen and compiled at sittings 9 and 9b')
SITTING = 'THE NUMBERS WALK sitting 10 — THE VOWS'
verses = list(range(1, 18))
sif_cites = [f'Sifrei Bamidbar {p}:{r}' for p in PISKAOT for r in range(1, SIF_ROWS[p] + 1)]
cites = [f'Onkelos Num 30:{v}' for v in verses] + sif_cites
N_ALL = len(cites); NS = len(sif_cites); NO = len(verses)
cnt = Counter(R[(30, v)][0] for v in verses); scnt = Counter(S[(p, r)][0] for p in PISKAOT for r in range(1, SIF_ROWS[p] + 1))
heads_txt = ', '.join(f'{p} on {head(p)[0]}:{head(p)[1]}{" (opening on 30:15 — the head mistyped)" if p == 156 else ""} ({SIF_ROWS[p]} row{"s" if SIF_ROWS[p] > 1 else ""})' for p in PISKAOT)
hdr = (f'# Numbers 30:1-17 derivation — Onkelos + the Sifrei on Numbers as the spine (its piskaot found BY POSITION), '
       f'{SITTING}, {TITLE} ({DATE}; the owner: "Go" after the #141 rereads, on the ruling NUMBERS IN ORDER FROM 1:1 and READ THEN COMPILE). '
       f'DECLARED (THE_STEPS Step 2, the spine default of 2026-08-27, read at the PARASHAH GRAIN — speed ruling (a): {DECL}): scope = Onkelos Numbers 30:1-17 ({NO} verses, fresh) '
       f'+ the Sifrei on Numbers piskaot {heads_txt} BY POSITION ({NS} rows at the shelf\'s row grain; the rows\' own defects read to their verses — RESEARCH_LOG.md; every head asserted between its neighbors; the Sifrei has no piska on 30:1 — 152:1\'s, read whole at sitting 9 and CREDITED here). {TESTING} OUTSIDE DECLARED SCOPE, enumerated and unread (the shelf\'s other works on Numbers, {len(outside)} directories): {", ".join(outside)}.\n\n')
body = f'## Sifrei Bamidbar piskaot 153-156 ({NS} rows, read whole — the heads by position: {heads_txt})\n'
for p in PISKAOT:
    for r in range(1, SIF_ROWS[p] + 1):
        verdict, prose = S[(p, r)]
        body += f'- Sifrei Bamidbar {p}:{r} — {verdict}. {prose}\n'
body += '- Sifrei Bamidbar 152:1 — CREDITED (read whole at sitting 9, num_29_fall_festivals_2026-09-11.md; quick look: its standing row reads 30:1 as the calendar\'s closer — "and Moses said to the children of Israel" as punctuation, R. Yishmael — exactly this draft\'s first verse; not counted among the fresh rows).\n'
body += f'\n## Onkelos Numbers 30:1-17 ({NO} verses, read whole)\n'
for v in verses:
    verdict, prose = R[(30, v)]
    body += f'- Onkelos Num 30:{v} — {verdict}. {prose}\n'
body += '\n## The ink beside the shelf (computed by this script from the Tanakh DB, the snapshot store and the shelf — never recited)\n'
body += SHELF + '\n' + PARSER + '\n' + REGISTER + '\n'
for line in INK: body += line + '\n'
body += '\n## The finds (this ledger\'s crowns)\n' + '\n'.join(CROWNS) + '\n'
body += (f'\n## CITE INDEX — every source opened, each fully named\n(one name per line; coverage COMPUTED against the shelf by the ledger script write_vows_ledger.py: Onkelos Numbers 30:1-17 {NO} verses — missing 0, extra 0; the Sifrei on Numbers piskaot 153-156, {NS} rows at the shelf\'s own row counts — missing 0, extra 0)\n')
body += '\n'.join(cites) + '\n'
body += f'({NO} Onkelos verses fresh + {NS} Sifrei Bamidbar rows fresh = {N_ALL} sources in this ledger; the Sifrei\'s 152:1 credited beside them, not counted.)\n\n'
body += (f'**read: {N_ALL} of {N_ALL} — COMPLETE** ({NO} Onkelos verses and {NS} Sifrei rows opened and verdicted this sitting at the shelf\'s row grain, coverage computed by script — missing 0, extra 0; '
         f'verdicts MATERIAL {cnt["MATERIAL"]} Onkelos, CONTEXT {cnt["CONTEXT"]} Onkelos, MATERIAL {scnt["MATERIAL"]} Sifrei, CONTEXT {scnt["CONTEXT"]} Sifrei — the counts the script\'s own Counter measured)\n')
assert FAIL == [], FAIL
open(OUT, 'w', encoding='utf-8').write(hdr + body)
print(f'wrote {OUT}: {N_ALL} sources, Onkelos MATERIAL {cnt["MATERIAL"]} / CONTEXT {cnt["CONTEXT"]}; Sifrei {NS} rows MATERIAL {scnt["MATERIAL"]} / CONTEXT {scnt["CONTEXT"]}; bytes {len((hdr + body).encode())}')
